import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  inOutEnvelope,
} from "../motion";

export const fps = 25;
export const durationInFrames = 165; // 20 (bookend) + 125 (scene + transition overlap) + 25 (bookend) - 5 overlap math below

const TRANSITION = 15;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const ACCENT = COLORS.orange;

const HEADLINE_LEAD = "TripAdvisor Reviews Scraper —";
const HEADLINE_HIGHLIGHT = "every review, every property";
const HEADLINE_TAIL = ".";

const BULLETS = [
  "50+ reviews/min",
  "ratings, dates, and reviewer profiles",
  "export to CSV or JSON",
];

// --- Background ---
const Background: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// --- Crosshair "+" decoration ---
const Crosshair: React.FC<{
  x: number;
  y: number;
  size: number;
  opacity: number;
  seed: string;
}> = ({ x, y, size, opacity, seed }) => {
  const frame = useCurrentFrame();
  const driftX = ambientDrift(frame, 1.5, 140, `cx-${seed}`);
  const driftY = ambientDrift(frame, 1.5, 160, `cy-${seed}`);
  const stroke = Math.max(2, size * 0.08);
  return (
    <svg
      style={{
        position: "absolute",
        left: `${x * 100}%`,
        top: `${y * 100}%`,
        width: size,
        height: size,
        transform: `translate(calc(-50% + ${driftX}px), calc(-50% + ${driftY}px))`,
        opacity,
      }}
      viewBox="0 0 24 24"
    >
      <line
        x1="12"
        y1="2"
        x2="12"
        y2="22"
        stroke={ACCENT}
        strokeWidth={stroke}
        strokeLinecap="round"
      />
      <line
        x1="2"
        y1="12"
        x2="22"
        y2="12"
        stroke={ACCENT}
        strokeWidth={stroke}
        strokeLinecap="round"
      />
    </svg>
  );
};

// --- Checkmark icon with stroke-draw reveal ---
const CheckIcon: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      style={{ flexShrink: 0 }}
    >
      <path
        d="M5 12.5 L10 17.5 L19 7"
        stroke={ACCENT}
        strokeWidth={3}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        strokeDasharray={28}
        strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
        opacity={progress}
      />
    </svg>
  );
};

// --- Bullet row sub-component ---
const BulletRow: React.FC<{
  label: string;
  index: number;
  baseDelay: number;
  base: number;
}> = ({ label, index, baseDelay, base }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const itemIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay,
    TIMING.staggerItem,
    "GENTLE"
  );
  const driftY = ambientDrift(frame, 1.2, 110 + index * 17, `row-${index}`);
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: base * 0.02,
        opacity: itemIn,
        transform: `translateX(${interpolate(
          itemIn,
          [0, 1],
          [-base * 0.025, 0]
        )}px) translateY(${driftY}px)`,
      }}
    >
      <CheckIcon size={base * 0.034} progress={itemIn} />
      <div
        style={{
          fontFamily: "Inter, sans-serif",
          fontWeight: 500,
          fontSize: base * 0.028,
          color: COLORS.text,
          letterSpacing: "-0.005em",
          lineHeight: 1.25,
        }}
      >
        {label}
      </div>
    </div>
  );
};

// --- Main Scene ---
const HeroCard: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const envelope = inOutEnvelope(frame, vfps, durationInFrames);

  const headerIn = springIn(frame, vfps, 0, "GENTLE");
  const titleIn = springIn(frame, vfps, TIMING.entrance, "SNAPPY");
  const highlightIn = springIn(frame, vfps, TIMING.entrance + 8, "LIQUID");
  const decoIn = springIn(frame, vfps, TIMING.entrance + 30, "GENTLE");

  // Subtle hero drift during hold
  const titleDriftY = ambientDrift(frame, 2.5, 130, "title-drift");

  const wordmarkH = base * 0.05;
  const headlineSize = base * 0.072;

  return (
    <AbsoluteFill style={{ opacity: envelope }}>
      <Background />

      {/* Decorative crosshairs */}
      <Crosshair
        x={0.07}
        y={0.14}
        size={base * 0.022}
        opacity={decoIn * 0.55}
        seed="tl"
      />
      <Crosshair
        x={0.93}
        y={0.18}
        size={base * 0.022}
        opacity={decoIn * 0.5}
        seed="tr"
      />
      <Crosshair
        x={0.1}
        y={0.86}
        size={base * 0.022}
        opacity={decoIn * 0.5}
        seed="bl"
      />
      <Crosshair
        x={0.9}
        y={0.82}
        size={base * 0.022}
        opacity={decoIn * 0.45}
        seed="br"
      />

      {/* Wordmark */}
      <div
        style={{
          position: "absolute",
          left: base * 0.045,
          top: base * 0.045,
          opacity: headerIn,
          transform: `translateY(${interpolate(
            headerIn,
            [0, 1],
            [-10, 0]
          )}px)`,
        }}
      >
        <Img
          src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
          style={{ height: wordmarkH, width: "auto" }}
        />
      </div>

      {/* Content column — off-center left-anchored */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "26%",
          width: "78%",
          display: "flex",
          flexDirection: "column",
          gap: base * 0.045,
          transform: `translateY(${titleDriftY}px)`,
        }}
      >
        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: headlineSize,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.08,
            opacity: titleIn,
            transform: `translateY(${interpolate(
              titleIn,
              [0, 1],
              [28, 0]
            )}px)`,
            maxWidth: "92%",
          }}
        >
          <span style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
            {HEADLINE_LEAD}{" "}
          </span>
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.0032)}px solid ${ACCENT}`,
              padding: `0 ${base * 0.012}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(
                highlightIn,
                [0, 1],
                [100, 0]
              )}% 0 0)`,
              display: "inline-block",
            }}
          >
            {HEADLINE_HIGHLIGHT}
          </span>
          <span style={{ fontFamily: "'GT Walsheim', Inter, sans-serif" }}>
            {HEADLINE_TAIL}
          </span>
        </div>

        {/* Bullet rows */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: base * 0.024,
            marginTop: base * 0.015,
          }}
        >
          {BULLETS.map((label, i) => (
            <BulletRow
              key={i}
              label={label}
              index={i}
              baseDelay={TIMING.entrance + 22}
              base={base}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// --- Composition ---
const SCENE_DURATION = 125;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence
        durationInFrames={SCENE_DURATION + TRANSITION}
      >
        <HeroCard />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
